const items = $input.all().map(item => item.json);

const subject =
  "Daily RSS News Digest | Space, Science & Inspiring Ideas";

const categories = {
  "NASA - Space & Universe": [],
  "ScienceDaily - Science & Discoveries": [],
  "TED - Motivation & Ideas": [],
  "Other RSS News": []
};

function cleanText(value) {
  return String(value || "")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

for (const item of items) {
  const url = item.link || item.url || "";
  const domain = url.toLowerCase();

  let category = "Other RSS News";

  if (domain.includes("nasa.gov")) {
    category = "NASA - Space & Universe";
  } else if (domain.includes("sciencedaily.com")) {
    category = "ScienceDaily - Science & Discoveries";
  } else if (domain.includes("ted.com")) {
    category = "TED - Motivation & Ideas";
  }

  const title = cleanText(item.title) || "Untitled Article";

  const summary = cleanText(
    item.contentSnippet ||
    item.description ||
    item.summary ||
    item["content:encoded"] ||
    item.content ||
    "No summary was provided in the RSS feed."
  );

  const date = cleanText(
    item.isoDate || item.pubDate || item.date || ""
  );

  if (categories[category].length >= 10) continue;

  categories[category].push({
    title,
    date: date || "Date unavailable",
    summary: summary.slice(0, 2000),
    url: url || "Article URL unavailable"
  });
}

let body =
  "Hello!\n\n" +
  "Welcome to your Daily RSS News Digest. " +
  "Here are the latest articles received from your selected RSS feeds.\n";

for (const [category, articles] of Object.entries(categories)) {
  body += "\n\n================================\n";
  body += category + "\n";
  body += "================================\n";

  if (articles.length === 0) {
    body += "No new articles received from this source.\n";
    continue;
  }

  articles.forEach((article, index) => {
    body += `\n${index + 1}. ${article.title}\n`;
    body += `Published: ${article.date}\n`;
    body += `Summary: ${article.summary}\n`;
    body += `Original Link: ${article.url}\n`;
  });
}

body +=
  "\n\nThank you for reading your Daily News Digest!\n" +
  "Stay curious and keep learning.";

return [
  {
    json: {
      subject,
      body,
      totalArticles: items.length
    }
  }
];
